    result = []
    balance = 0
    current_group = ''

    for char in paren_string.replace(' ', ''):
        if char == '(':
            balance += 1
            current_group += char
        elif char == ')':
            balance -= 1
            current_group += char

            if balance == 0:
                result.append(current_group)
                current_group = ''

    return result

